const CHART_HEIGHT = 640;

const tooltip = d3.select('#tooltip');
const legend = d3.select('#legend');
const tableBody = d3.select('#stock-table tbody');
const bubbleSvg = d3.select('#bubble-chart');
const bubbleWrap = document.querySelector('.chart-wrap');
const sparkSvg = d3.select('#price-chart');
const sparkTitle = d3.select('#sparkline-title');
const sparkRange = d3.select('#sparkline-range');

const parseDate = d3.timeParse('%Y-%m-%d');

function formatMarketCap(value) {
  if (value === null || value === undefined || isNaN(value)) return 'N/A';
  const abs = Math.abs(value);
  if (abs >= 1e12) return `${(value / 1e12).toFixed(2)}T`;
  if (abs >= 1e9) return `${(value / 1e9).toFixed(2)}B`;
  if (abs >= 1e6) return `${(value / 1e6).toFixed(2)}M`;
  if (abs >= 1e3) return `${(value / 1e3).toFixed(2)}K`;
  return value.toFixed(0);
}

function parseDescriptionRow(row) {
  const marketCap = row.marketCap ? +row.marketCap : null;
  return {
    ticker: row.ticker,
    sector: row.sector || 'Other',
    fullName: row['full name'] || row.fullName || row.name,
    marketCap,
    country: row.country || null,
    website: row.website || null,
    isETF: !marketCap || row.sector === 'ETF'
  };
}

function parseHistoryRow(row) {
  const closeValue = row['Adjusted Close'] || row['Adj Close'] || row.Close || row.close;
  return {
    date: parseDate(row.Date || row.date),
    close: closeValue ? +closeValue : null
  };
}

function computeSectorCenters(sectors, width, height) {
  const cols = Math.ceil(Math.sqrt(sectors.length));
  const rows = Math.ceil(sectors.length / cols);
  const gridW = width * 0.7;
  const gridH = height * 0.65;
  const startX = (width - gridW) / 2;
  const startY = (height - gridH) / 2;
  const xStep = cols > 1 ? gridW / (cols - 1) : 0;
  const yStep = rows > 1 ? gridH / (rows - 1) : 0;
  const centers = {};

  sectors.forEach((sector, index) => {
    const col = index % cols;
    const row = Math.floor(index / cols);
    centers[sector] = {
      x: startX + (cols > 1 ? col * xStep : gridW / 2),
      y: startY + (rows > 1 ? row * yStep : gridH / 2)
    };
  });

  return centers;
}

function buildLegend(sectors, color) {
  legend.selectAll('*').remove();
  const items = legend.selectAll('.legend-item')
    .data(sectors)
    .enter()
    .append('div')
    .attr('class', 'legend-item');

  items.append('span')
    .attr('class', 'legend-swatch')
    .style('background', d => color(d));

  items.append('span').text(d => d);
}

function renderTable(data, onSelect) {
  tableBody.selectAll('tr')
    .data(data)
    .enter()
    .append('tr')
    .attr('data-ticker', d => d.ticker)
    .on('click', (event, d) => onSelect(d.ticker))
    .selectAll('td')
    .data(d => [
      d.ticker,
      d.fullName,
      d.sector,
      formatMarketCap(d.marketCap)
    ])
    .enter()
    .append('td')
    .text(d => d);
}

function renderSparkline(historyByTicker, ticker) {
  sparkSvg.selectAll('*').remove();

  if (!ticker) {
    sparkTitle.text('Select a stock to view its price history');
    sparkRange.text('');
    return;
  }

  const series = historyByTicker.get(ticker) || [];
  if (!series.length) {
    sparkTitle.text(`${ticker} has no price history available`);
    sparkRange.text('');
    return;
  }

  const cleaned = series.filter(d => d.date && !isNaN(d.close));
  cleaned.sort((a, b) => a.date - b.date);

  const rect = sparkSvg.node().getBoundingClientRect();
  const width = rect.width || 400;
  const height = rect.height || 160;
  const margin = { top: 10, right: 18, bottom: 20, left: 36 };

  sparkSvg.attr('viewBox', `0 0 ${width} ${height}`);

  const x = d3.scaleTime()
    .domain(d3.extent(cleaned, d => d.date))
    .range([margin.left, width - margin.right]);

  const y = d3.scaleLinear()
    .domain(d3.extent(cleaned, d => d.close))
    .nice()
    .range([height - margin.bottom, margin.top]);

  sparkTitle.text(`${ticker} price history`);
  sparkRange.text(`${d3.timeFormat('%b %Y')(x.domain()[0])} - ${d3.timeFormat('%b %Y')(x.domain()[1])}`);

  sparkSvg.append('path')
    .datum(cleaned)
    .attr('fill', 'none')
    .attr('stroke', '#cc6b3c')
    .attr('stroke-width', 2)
    .attr('d', d3.line()
      .x(d => x(d.date))
      .y(d => y(d.close))
    );

  sparkSvg.append('g')
    .attr('transform', `translate(0,${height - margin.bottom})`)
    .call(d3.axisBottom(x).ticks(4).tickSizeOuter(0));

  sparkSvg.append('g')
    .attr('transform', `translate(${margin.left},0)`)
    .call(d3.axisLeft(y).ticks(4).tickSizeOuter(0));
}

function renderBubbleChart(data, historyByTicker) {
  const sectors = Array.from(new Set(data.map(d => d.sector))).sort();
  const colorPalette = d3.schemeTableau10.concat(d3.schemeSet3);
  const color = d3.scaleOrdinal(sectors, colorPalette);
  buildLegend(sectors, color);

  const capValues = data.filter(d => d.marketCap).map(d => d.marketCap);
  const radiusScale = d3.scaleSqrt()
    .domain(d3.extent(capValues))
    .range([14, 50]);

  data.forEach(d => {
    d.radius = d.marketCap ? radiusScale(d.marketCap) : 18;
  });

  const nodes = bubbleSvg.selectAll('.node')
    .data(data)
    .enter()
    .append('g')
    .attr('class', 'node');

  nodes.append('circle')
    .attr('r', d => d.radius)
    .attr('fill', d => color(d.sector));

  nodes.append('text')
    .text(d => d.ticker)
    .style('font-size', d => `${Math.max(9, d.radius * 0.4)}px`);

  let selectedTicker = null;

  function setSelected(ticker) {
    selectedTicker = ticker;
    nodes.classed('selected', d => d.ticker === ticker);
    tableBody.selectAll('tr')
      .classed('selected', d => d.ticker === ticker);

    const row = tableBody.selectAll('tr').filter(d => d.ticker === ticker).node();
    if (row) {
      row.scrollIntoView({ block: 'center', behavior: 'smooth' });
    }

    renderSparkline(historyByTicker, ticker);
  }

  nodes.on('click', (event, d) => setSelected(d.ticker));

  nodes.on('mouseenter', function(event, d) {
    d3.select(this).classed('hovered', true);
    if (d.isETF) return;
    tooltip
      .style('opacity', 1)
      .attr('aria-hidden', 'false')
      .html(`<strong>${d.ticker}</strong>${d.fullName}<br/>${d.sector}`);
  })
    .on('mousemove', (event, d) => {
      if (d.isETF) return;
      tooltip
        .style('left', `${event.pageX + 12}px`)
        .style('top', `${event.pageY - 12}px`);
    })
    .on('mouseleave', function(event, d) {
      d3.select(this).classed('hovered', false);
      tooltip.style('opacity', 0).attr('aria-hidden', 'true');
    });

  function resize() {
    const width = bubbleWrap.clientWidth;
    const height = bubbleWrap.clientHeight || CHART_HEIGHT;
    bubbleSvg.attr('viewBox', `0 0 ${width} ${height}`);

    const centers = computeSectorCenters(sectors, width, height);

    simulation.force('x', d3.forceX(d => centers[d.sector].x).strength(0.35));
    simulation.force('y', d3.forceY(d => centers[d.sector].y).strength(0.35));
    simulation.force('center', d3.forceCenter(width / 2, height / 2));

    simulation.alpha(0.7).restart();
  }

  const simulation = d3.forceSimulation(data)
    .force('x', d3.forceX().strength(0.35))
    .force('y', d3.forceY().strength(0.35))
    .force('center', d3.forceCenter())
    .force('collide', d3.forceCollide(d => d.radius + 2))
    .alphaDecay(0.03)
    .on('tick', () => {
      nodes.attr('transform', d => `translate(${d.x},${d.y})`);
    });

  resize();
  window.addEventListener('resize', () => {
    resize();
    renderSparkline(historyByTicker, selectedTicker);
  });

  return { setSelected };
}

function loadData() {
  d3.csv('./data/stock-descriptions.csv', parseDescriptionRow).then(data => {
    const historyPromises = data.map(d => {
      const fileName = d.sector === 'ETF' ? d.ticker.toLowerCase() : d.ticker;
      return d3.csv(`./data/indiv-stock/${fileName}.csv`, parseHistoryRow)
        .then(rows => [d.ticker, rows])
        .catch(() => [d.ticker, []]);
    });

    Promise.all(historyPromises).then(historyEntries => {
      const historyByTicker = new Map(historyEntries);
      const bubble = renderBubbleChart(data, historyByTicker);
      renderTable(data, bubble.setSelected);
      renderSparkline(historyByTicker, null);
    });
  });
}

loadData();
